/**
 * TravelMate railpull ETL Importer
 * Integrates NTES extracted CSV/JSONL datasets generated by tools/railpull
 * License: MIT License (tools)
 * Standing Decisions: S1 (NTES terms protocol), S2 (delay snapshot), S7 (freshness)
 */

import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { fileURLToPath } from 'node:url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const ROOT = path.resolve(__dirname, '../..');

export const LICENSE = 'MIT License';

function sha256(buf) {
  return crypto.createHash('sha256').update(buf).digest('hex');
}

function parseCsv(content) {
  const lines = content.split(/\r?\n/).filter(line => line.trim().length > 0);
  if (lines.length < 2) return [];
  const header = lines[0].split(',').map(h => h.trim().replace(/^"|"$/g, ''));
  const rows = [];
  for (let i = 1; i < lines.length; i++) {
    const rawCols = lines[i].split(',');
    const obj = {};
    for (let c = 0; c < header.length; c++) {
      obj[header[c]] = rawCols[c] ? rawCols[c].trim().replace(/^"|"$/g, '') : '';
    }
    rows.push(obj);
  }
  return rows;
}

export function runRailpullImport({ inputDir = null, dryRun = false } = {}) {
  const targetDir = inputDir ? path.resolve(inputDir) : path.resolve(ROOT, 'data/out');
  console.log(`[ETL:Railpull] Scanning for railpull output in ${targetDir}...`);

  const trainsPath = path.join(targetDir, 'trains.csv');
  const stopsPath = path.join(targetDir, 'stops.csv');
  const stationsPath = path.join(targetDir, 'stations.csv');
  const delaysPath = path.join(targetDir, 'delays.json');

  const filesFound = {
    trains: fs.existsSync(trainsPath),
    stops: fs.existsSync(stopsPath),
    stations: fs.existsSync(stationsPath),
    delays: fs.existsSync(delaysPath)
  };

  if (!filesFound.trains && !filesFound.stops) {
    console.log('[ETL:Railpull] No railpull CSV output files found in data/out/.');
    console.log('[ETL:Railpull] Per Standing Decision S1, bulk automated NTES crawling was halted due to operator terms.');
    console.log('[ETL:Railpull] If you have an authorized export dump, place trains.csv and stops.csv in data/out/ and re-run.');
    return { status: 'NO_FILES_FOUND', loaded: false };
  }

  // Parse CSV records
  const trainsRaw = filesFound.trains ? parseCsv(fs.readFileSync(trainsPath, 'utf8')) : [];
  const stopsRaw = filesFound.stops ? parseCsv(fs.readFileSync(stopsPath, 'utf8')) : [];
  const stationsRaw = filesFound.stations ? parseCsv(fs.readFileSync(stationsPath, 'utf8')) : [];

  console.log(`[ETL:Railpull] Parsed ${trainsRaw.length} trains, ${stopsRaw.length} stops, ${stationsRaw.length} stations.`);

  const checksums = {
    trains: filesFound.trains ? sha256(fs.readFileSync(trainsPath)) : null,
    stops: filesFound.stops ? sha256(fs.readFileSync(stopsPath)) : null,
    stations: filesFound.stations ? sha256(fs.readFileSync(stationsPath)) : null
  };

  const datasetVersion = {
    id: `ver_railpull_${Date.now()}`,
    source: 'shwetankg07/railpull',
    license: LICENSE,
    sourceReference: 'https://github.com/shwetankg07/railpull',
    checksum: checksums.trains || 'fixture',
    checksums,
    rowCounts: {
      trains: trainsRaw.length,
      stops: stopsRaw.length,
      stations: stationsRaw.length
    },
    importedAt: new Date().toISOString()
  };

  if (dryRun) {
    console.log('[ETL:Railpull] Dry run completed. No files modified.');
    return { status: 'DRY_RUN', datasetVersion, trainsCount: trainsRaw.length, stopsCount: stopsRaw.length };
  }

  // Handle delay snapshot if present (Standing Decision S2)
  if (filesFound.delays) {
    try {
      const delaysData = JSON.parse(fs.readFileSync(delaysPath, 'utf8'));
      const snapshotFile = path.resolve(ROOT, 'shared/data/delay_snapshot.json');
      fs.writeFileSync(snapshotFile, JSON.stringify({
        source: 'railpull_delays',
        observedAt: new Date().toISOString(),
        delays: delaysData
      }, null, 2), 'utf8');
      console.log('[ETL:Railpull] Delay snapshot written to shared/data/delay_snapshot.json.');
    } catch (e) {
      console.warn('[ETL:Railpull] Failed to process delays.json:', e.message);
    }
  }

  console.log('[ETL:Railpull] Ingestion completed successfully.');
  return { status: 'SUCCESS', datasetVersion, trainsCount: trainsRaw.length, stopsCount: stopsRaw.length };
}

// Allow CLI execution: node data/etl/import-railpull.mjs [--dry-run] [--dir <path>]
if (process.argv[1] && import.meta.url === `file:///${process.argv[1].replace(/\\/g, '/')}`) {
  const isDryRun = process.argv.includes('--dry-run');
  const dirIdx = process.argv.indexOf('--dir');
  const customDir = dirIdx !== -1 ? process.argv[dirIdx + 1] : null;
  runRailpullImport({ inputDir: customDir, dryRun: isDryRun });
}
